  display: flex;
  flex-direction: row;

  .left {
    flex-shrink: 1;
    display: flex;
    align-items: center;
  }

  .right {
    flex-grow: 1;
    display: flex;
    align-items: center;
  }
}

.insights-column {
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
}
